import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"Harvester Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"harvester/configuration.md","filePath":"harvester/configuration.md","lastUpdated":1792785127000}'),n={name:"harvester/configuration.md"};function o(l,e,r,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="harvester-configuration" tabindex="-1">Harvester Configuration <a class="header-anchor" href="#harvester-configuration" aria-label="Permalink to &quot;Harvester Configuration&quot;">​</a></h1><p><code>geomilli-harvester</code> is the ingestion engine responsible for downloading OpenStreetMap data from Geofabrik, filtering tags via <code>osmium</code>, normalizing taxonomy entities, performing Wikidata enrichment, and indexing into Meilisearch.</p><hr><h2 id="_1-environment-variables" tabindex="-1">1. Environment Variables <a class="header-anchor" href="#_1-environment-variables" aria-label="Permalink to &quot;1. Environment Variables&quot;">​</a></h2><p>The harvester is configured entirely through environment variables or CLI flags:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>COUNTRIES</code></td><td style="text-align:left;"><code>BE</code></td><td style="text-align:left;">Comma-separated ISO alpha-2 country codes (e.g. <code>BE</code>, <code>BE,NL,LU</code>, or <code>ALL</code>).</td></tr><tr><td style="text-align:left;"><code>MEILI_HOST</code></td><td style="text-align:left;"><code>http://127.0.0.1:7700</code></td><td style="text-align:left;">Target Meilisearch server URL.</td></tr><tr><td style="text-align:left;"><code>MEILI_API_KEY</code></td><td style="text-align:left;"><code>masterKey123</code></td><td style="text-align:left;">Meilisearch Admin / Master API key.</td></tr><tr><td style="text-align:left;"><code>ONLINE_ENRICH</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">Enable online Wikidata and Wikipedia Pageviews API queries. When <code>false</code>, uses offline heuristics.</td></tr><tr><td style="text-align:left;"><code>PORT</code> or <code>HARVESTER_PORT</code></td><td style="text-align:left;"><code>8085</code></td><td style="text-align:left;">HTTP and SSE control daemon port.</td></tr><tr><td style="text-align:left;"><code>DATA_DIR</code></td><td style="text-align:left;"><code>./data</code></td><td style="text-align:left;">Base directory for disk caching, SQLite WAL databases, and staging files.</td></tr><tr><td style="text-align:left;"><code>OSM_GEOFABRIK_BASE_URL</code></td><td style="text-align:left;"><code>https://download.geofabrik.de</code></td><td style="text-align:left;">Geofabrik mirror base URL.</td></tr><tr><td style="text-align:left;"><code>ENRICH_QPS</code></td><td style="text-align:left;"><code>3</code></td><td style="text-align:left;">Maximum rate-limited QPS for external Wikipedia API calls.</td></tr><tr><td style="text-align:left;"><code>ENRICH_CACHE_TTL_DAYS</code></td><td style="text-align:left;"><code>30</code></td><td style="text-align:left;">Retention window for SQLite enrichment cache.</td></tr></tbody></table><hr><h2 id="_2-country-selection-the-default-be" tabindex="-1">2. Country Selection &amp; The Default (<code>BE</code>) <a class="header-anchor" href="#_2-country-selection-the-default-be" aria-label="Permalink to &quot;2. Country Selection &amp; The Default (\`BE\`)&quot;">​</a></h2><p>To ensure a friction-free local developer experience, Geomilli defaults to <strong>Belgium (<code>BE</code>)</strong> (<code>europe/belgium-latest.osm.pbf</code>):</p><ul><li>PBF Download Size: ~70 MB</li><li>Filtered GeoJSON: ~180,000 places &amp; amenities</li><li>Processing Time: ~60–90 seconds on standard laptops</li></ul><h3 id="configuring-additional-countries" tabindex="-1">Configuring Additional Countries <a class="header-anchor" href="#configuring-additional-countries" aria-label="Permalink to &quot;Configuring Additional Countries&quot;">​</a></h3><p>To index other countries, set <code>COUNTRIES</code> in <code>.env</code>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ingest the Benelux union</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">COUNTRIES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BE,NL,LU</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ingest all supported countries</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># COUNTRIES=ALL</span></span></code></pre></div><p>Country definitions and URL paths are resolved against <code>config/countries.yaml</code>.</p><hr><h2 id="_3-operational-modes-daemon-vs-cli" tabindex="-1">3. Operational Modes: Daemon vs CLI <a class="header-anchor" href="#_3-operational-modes-daemon-vs-cli" aria-label="Permalink to &quot;3. Operational Modes: Daemon vs CLI&quot;">​</a></h2><p>The harvester binary provides two operational patterns:</p><h3 id="a-daemon-mode-harvester-serve" tabindex="-1">A. Daemon Mode (<code>harvester serve</code>) <a class="header-anchor" href="#a-daemon-mode-harvester-serve" aria-label="Permalink to &quot;A. Daemon Mode (\`harvester serve\`)&quot;">​</a></h3><p>Used in Docker Compose and persistent container deployments. It boots a lightweight HTTP server on port <code>8085</code>:</p><ul><li>Listens for trigger jobs from <code>geomilli-studio</code> or <code>geomilli-api</code>.</li><li>Emits real-time Server-Sent Events (SSE) tracking pipeline progress, records/sec, and memory footprint.</li><li>Runs an initial import on startup if the <code>places</code> index does not exist.</li></ul><h3 id="b-one-shot-cli-mode-harvester-run" tabindex="-1">B. One-Shot CLI Mode (<code>harvester run</code>) <a class="header-anchor" href="#b-one-shot-cli-mode-harvester-run" aria-label="Permalink to &quot;B. One-Shot CLI Mode (\`harvester run\`)&quot;">​</a></h3><p>Ideal for CI/CD pipelines, Airflow tasks, or Kubernetes CronJobs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ingest Belgium and exit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">geomilli-harvester</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --countries=BE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --online-enrich=true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Custom index name without swapping</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">geomilli-harvester</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --countries=NL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-name=places_nl</span></span></code></pre></div><hr><h2 id="_4-harvester-control-api" tabindex="-1">4. Harvester Control API <a class="header-anchor" href="#_4-harvester-control-api" aria-label="Permalink to &quot;4. Harvester Control API&quot;">​</a></h2><p>When running in daemon mode, the harvester exposes an internal HTTP API:</p><ul><li><code>GET /api/v1/countries</code>: Returns supported country codes, their status (<code>indexed</code>, <code>cached</code>, <code>queued</code>), and file sizes.</li><li><code>POST /api/v1/jobs</code>: Triggers an asynchronous import job.<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;countries&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LU&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;online_enrich&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;append&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><code>GET /api/v1/status</code>: Returns current stage, progress percentage, records processed, and Go runtime memory stats (<code>HeapAlloc</code>, <code>Sys</code>, <code>NumGC</code>).</li><li><code>GET /api/v1/events</code>: Subscribes to real-time Server-Sent Events (SSE) for UI progress bars.</li></ul>`,27)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
